/**
 * TASK: Complete the SalesReport class (Template Method pattern).
 *
 * The abstract Report base class above fixes the report skeleton in its
 * FINAL build() method: header() + "|" + body() + "|" + footer().
 * Subclasses customize the steps, never the skeleton.
 *
 * SalesReport must:
 *   - implement body() to return "sales"
 *   - override header() to return "SALES"
 *   - leave footer() alone (the inherited "F" is kept)
 *
 * Example: new SalesReport().build() -> "SALES|sales|F"
 */
abstract class Report {
    final String build() {
        return header() + "|" + body() + "|" + footer();
    }

    String header() {
        return "H";
    }

    String footer() {
        return "F";
    }

    abstract String body();
}

public class SalesReport extends Report {

    String body() {
        // TODO: return the body text
        return "";
    }

    // TODO: override header() to return "SALES"
}

