public class SalesReportTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            SalesReport report = new SalesReport();
            check("build() assembles the full report", "SALES|sales|F", report.build());
            check("header() is overridden", "SALES", report.header());
            check("body() is implemented", "sales", report.body());
            check("footer() keeps the inherited default", "F", report.footer());
            Report asBase = new SalesReport();
            check("build() via the base-class reference", "SALES|sales|F", asBase.build());
            check("two instances agree", new SalesReport().build(), report.build());
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception -- " + e.getClass().getSimpleName());
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

